#!/usr/bin/env python3
"""Compiled entity loop: conversion pulse, G/H transition and shared projectile cleanup."""
from pathlib import Path
import hashlib,json,re,subprocess
r=Path(__file__).resolve().parents[1];o=r/'out/parity-audit/conversion-pulse-integration';o.mkdir(parents=True,exist_ok=True)
syms={n:int(v,16)&0xffffff for v,n in re.findall(r'^([0-9a-fA-F]+)\s+\w\s+(\w+)\s*$',(r/'out/symbol.txt').read_text(),re.M)}
rh=hashlib.sha256((r/'out/rom.bin').read_bytes()).hexdigest()
s='local cpu=manager.machine.devices[":maincpu"];local m=cpu.spaces.program\nlocal frame=0;local phase=0;local terminal=false;local checks=0\nlocal function clear(a,n)for k=0,n-1 do m:write_u8(a+k,0)end end\nlocal function check(v,why)checks=checks+1;assert(v,why)end\nlocal function run()\n for x=0xffb000,0xffb03e,2 do m:write_u16(x,0x4e71)end\n m:write_u16(0xffb040,0x4eb9);m:write_u32(0xffb042,FN);m:write_u16(0xffb046,0x60fe)\n cpu.state[\'SR\'].value=0x2700;cpu.state[\'SP\'].value=0xffbfe0;cpu.state[\'PC\'].value=0xffb000\nend\nlocal function finish(err)\n terminal=true;local f=assert(io.open(RESULT,\'w\'));f:write(string.format(\'{"updates":%d,"checks":%d,"error":%s}\',phase,checks,err and string.format(\'%q\',err)or\'null\'));f:close();manager.machine:exit()\nend\nemu.register_frame_done(function()\n if terminal then manager.machine:exit();return end;frame=frame+1;if frame<60 then return end\n local ok,err=pcall(function()\n if phase==0 then\n  clear(ENT,48*42);clear(GG,94);clear(FOES,240);clear(WEAPONS,72);clear(IA,96);clear(IW,10);clear(WAVES,106);clear(LARGE,102);clear(KPOOL,64)\n  m:write_u8(SURVIVAL,0);m:write_u8(GG+84,2);m:write_u8(GG+34,3);m:write_u8(GG+76,3)\n  m:write_u8(PULSE,1);m:write_u8(NEXT,0);m:write_u8(LIMIT,0)\n  for _,i in ipairs({0,6})do\n   local a=FOES+i*20;m:write_u16(a,100+i*10);m:write_u8(a+3,104);m:write_u8(a+5,1);m:write_u8(a+6,2);m:write_u8(a+9,1)\n   m:write_u8(ENT+i*42,1)\n  end\n  m:write_u16(KPOOL,100);m:write_u8(KPOOL+5,104);m:write_u8(KPOOL+7,1)\n  phase=1;run();return\n end\n check(cpu.state[\'CURPC\'].value&0xffffff==0xffb046,\'entity return\')\n check(m:read_u8(PULSE)==0,\'pulse cleared after actor pass\')\n for _,i in ipairs({0,6})do\n  local a=FOES+i*20\n  check(m:read_u8(a+6)==255,\'converted G/H state\')\n  check(m:read_u8(a+7)==(phase==1 and 0 or 1),\'conversion advances once next tick\')\n  if phase==2 then check(m:read_u8(a+14)==0,\'first conversion kind0\')end\n end\n if phase==1 then\n  check(m:read_u8(KPOOL+8)==3 and m:read_u8(KPOOL+9)==2,\'projectile purge\')\n  phase=2;run()\n else check(m:read_u8(KPOOL+7)==0,\'projectile cleanup\');finish()end\n end)\n if not ok then finish(err)end\nend)\n'
for k,v in {'ENT':syms['g_entities'],'GG':syms['g_game'],'FOES':syms['arcade_foes'],'WEAPONS':syms['arcade_weapons'],'IA':syms['arcade_i_actors'],'IW':syms['arcade_i_wave'],'WAVES':syms['arcade_waves'],'ILIVE':syms['arcade_i_live'],'IRES':syms['arcade_i_reservation'],'CLOCK':syms['wave_clock'],'SURVIVAL':syms['g_survivalRun'],'DIFFICULTY':syms['g_arcadeCombatDifficulty'],'PULSE':syms['arcade_food_conversion_pulse'],'NEXT':syms['arcade_bonus_next'],'LIMIT':syms['arcade_bonus_limit'],'KPOOL':syms['arcade_k_actors'],'LARGE':syms['arcade_large_actors'],'FN':syms['entity_update_all'],'RESULT':json.dumps(str(o/'results.json'))}.items():s=re.sub(r'\b'+k+r'\b',str(v),s)
(o/'run.lua').write_text(s)
subprocess.run(['mame','genesis','-cart',str(r/'out/rom.bin'),'-window','-nomaximize','-resolution','512x448','-video','none','-keyboardprovider','none','-mouseprovider','none','-joystickprovider','none','-noreadconfig','-sound','none','-nothrottle','-skip_gameinfo','-autoboot_script',str(o/'run.lua'),'-cfg_directory',str(o/'cfg'),'-nvram_directory',str(o/'nvram')],cwd=r,stdout=(o/'mame.log').open('w'),stderr=subprocess.STDOUT,timeout=120,check=True)
assert hashlib.sha256((r/'out/rom.bin').read_bytes()).hexdigest()==rh
result=json.loads((o/'results.json').read_text());result['rom_sha256']=rh;(o/'results.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2));assert result['error']is None and result['updates']==2,result
